return $input.all().map(item => {
  const d = item.json;
  // Eingang A (Webhook vom Listener-Bot) - n8n verschachtelt den POST-Body immer unter "body".
  if (d.body && d.body.event_id !== undefined) {
    const b = d.body;
    return { json: { event_id: b.event_id, room_id: b.room_id, sender: b.sender, text: b.text, reply_to: b.reply_to || '' } };
  }
  // Eingang B (Matrix "Get Many") liefert das native Matrix-Event-Format.
  const rel = (d.content && d.content['m.relates_to'] && d.content['m.relates_to']['m.in_reply_to']) || {};
  return {
    json: {
      event_id: d.event_id || d.eventId,
      room_id: d.room_id || d.roomId,
      sender: d.sender,
      text: (d.content && d.content.body) || d.body || '',
      reply_to: rel.event_id || ''
    }
  };
});

// Wandelt Allys Markdown-Antwort in das Chat-Layout um (Vorgabe Stefan, 11.10.2026):
// Titel fett mit Doppelpunkt, Inhalt direkt darunter, Leerzeile zwischen Bloecken, Aufzaehlungen als Zeilen mit Gedankenstrich, keine Emojis.
const ohneEmoji = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '').replace(/[ \t]{2,}/g, ' ').replace(/^ +/gm, '');
// Markdown-Tabellen kann der Chat nicht darstellen: jede Tabellenzeile wird ein Block mit fettem Titel (erste Spalte)
// und den übrigen Spalten als "Spalte: Wert" in einer Zeile.
function tabellenUmwandeln(text) {
  const z = text.split('\n');
  const istZeile = s => /^\s*\|.*\|\s*$/.test(s);
  const istTrenner = s => /^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$/.test(s);
  const zellen = s => s.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map(x => x.trim());
  const aus = [];
  let i = 0;
  while (i < z.length) {
    if (istZeile(z[i]) && i + 1 < z.length && istTrenner(z[i + 1])) {
      const kopf = zellen(z[i]).map(k => k.replace(/\*\*/g, ''));
      i += 2;
      while (i < z.length && istZeile(z[i])) {
        const r = zellen(z[i]);
        const titel = (r[0] || '').replace(/\*\*/g, '');
        const rest = r.slice(1).map((v, k) => v ? (/[A-Za-zÄÖÜäöüß]/.test(kopf[k + 1] || '') ? kopf[k + 1] + ': ' + v : v) : '').filter(Boolean).join(', ');
        aus.push('', '**' + titel + '**');
        if (rest) aus.push(rest);
        i++;
      }
      aus.push('');
      continue;
    }
    aus.push(z[i]);
    i++;
  }
  return aus.join('\n');
}
const md = tabellenUmwandeln(ohneEmoji($input.item.json.output || ''));

function esc(s) {
  return s.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
}
function inline(s) {
  s = esc(s);
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  s = s.replace(/`([^`]+)`/g, '<code>$1</code>');
  return s;
}
const ohneMd = s => s.replace(/\*\*([^*]+)\*\*/g, '$1').replace(/`([^`]+)`/g, '$1');

const bloecke = [];
let cur = null;
function neu() { if (cur && cur.h.length) bloecke.push(cur); cur = { h: [], t: [], nurTitel: false }; }
neu();
let quote = null;
function quoteAbschliessen() {
  if (!quote) return;
  neu();
  const z = quote.filter((x, i, a) => !(x.trim() === '' && (i === 0 || i === a.length - 1)));
  cur.h.push('<blockquote>' + z.map(x => x.trim() === '' ? '' : inline(x)).join('<br>') + '</blockquote>');
  cur.t.push(z.map(ohneMd).join('\n'));
  quote = null;
  neu();
}

for (const roh of md.split('\n')) {
  const t = roh.trim();
  if (t.startsWith('>')) { (quote = quote || []).push(t.replace(/^>\s?/, '')); continue; }
  quoteAbschliessen();
  if (t === '') { if (!cur.nurTitel) neu(); continue; }
  const titel = t.match(/^#{1,6}\s*(.+)$/) || t.match(/^\*\*([^*]+)\*\*:?$/);
  if (titel) {
    neu();
    let x = titel[1].replace(/\*\*/g, '').trim();
    if (!/[:?!.]$/.test(x)) x += ':';
    cur.h.push('<strong>' + inline(x) + '</strong>');
    cur.t.push(x);
    cur.nurTitel = true;
    continue;
  }
  let zeile = t;
  if (t.startsWith('- ') || t.startsWith('* ')) zeile = '– ' + t.slice(2);
  cur.h.push(inline(zeile));
  cur.t.push(ohneMd(zeile));
  cur.nurTitel = false;
}
quoteAbschliessen();
neu();

const html = bloecke.map(b => b.h.join('<br>')).join('<br><br>');
const plain = bloecke.map(b => b.t.join('\n')).join('\n\n');

return { json: { text: plain, html } };

