-- Absender-Regel speichern ueber dieselbe Funktion wie die Oberflaeche (Recht, eigene Domains, Postfach werden dort geprueft)
SELECT (r->>'ok')::boolean AS ok, r->>'meldung' AS status, r->>'muster' AS muster, r->>'kategorie' AS kategorie_key, r->>'postfach' AS gilt_fuer
FROM (SELECT mail_regel_speichern($4::text, $1::text, $2::text, $3::text, $5::text, 'ally') AS r) x;

-- Absender-Regel loeschen ueber dieselbe Funktion wie die Oberflaeche
SELECT (r->>'ok')::boolean AS ok, r->>'meldung' AS status
FROM (SELECT mail_regel_loeschen($2::text, $1::text, $3::text) AS r) x;

