// Eingang aufbereiten: Text für Ally (mit Antwortbezug und Zeitpunkt) und Bereich, wenn er schon feststeht.
// Antworten auf Klärungsnachrichten, Entwurfsangebote und Marketing-Vorschläge haben einen festen Bereich; sonst entscheidet die KI-Vorsortierung.
const e = $('6_4_eingang_zusammenfuehren').item.json;
const b = $('6_8d_antwortbezug_laden').item.json;
const k = $input.item.json;
const zeit = $now.setZone('Europe/Berlin').setLocale('de').toFormat('cccc, dd.MM.yyyy, HH:mm');
let prefix = '';
if (b.klaerungsfall_id) prefix += '[Nutzer antwortet direkt auf die Klärungsnachricht klaerung-' + b.klaerungsfall_id + ' (Status: ' + b.status + ', Betreff: ' + b.subject + ')]\n';
if (b.mail_rueckfrage_id) prefix += '[Nutzer antwortet direkt auf das Entwurfsangebot mail-' + b.mail_rueckfrage_id + ' (Von: ' + b.mail_absender + ', Betreff: ' + b.mail_betreff + ', Status: ' + b.mail_status + ')]\n';
if (b.marketing_themen) prefix += '[Nutzer antwortet direkt auf die Marketing-Themenvorschläge: ' + b.marketing_themen + ']\n';
let bereich = 'offen';
if (b.klaerungsfall_id) bereich = 'belege';
else if (b.mail_rueckfrage_id) bereich = 'mail';
else if (b.marketing_themen) bereich = 'marketing';
return { json: {
  sender: e.sender, room_id: e.room_id, text: e.text || '',
  sitzung: ($execution.mode === 'production' ? '' : 'test:') + e.sender,
  nutzer_name: b.nutzer_name, standard_postfach: b.standard_postfach, postfaecher: b.postfaecher, kalender_id: b.kalender_id,
  agent_text: prefix + (e.text || '') + '\n[Geschrieben: ' + zeit + ' Uhr]',
  bereich, quelle: bereich === 'offen' ? '' : 'antwortbezug',
  letzter_bereich: k.letzter_bereich || '', minuten_her: k.minuten_her, verlauf: k.verlauf || ''
} };

// Antwort der Vorsortierung auswerten; ohne eindeutiges Ergebnis bekommt Ally alle Werkzeuge
// Alle Text-Teile der KI-Antwort lesen: neuere Modelle liefern davor einen (leeren) thinking-Block (Stefan 18.10.2026)
const kiTeile = $input.item.json.content;
const raw = (Array.isArray(kiTeile) ? kiTeile : []).filter(b => b && b.type === 'text' && b.text).map(b => String(b.text)).join('\n');
// Bereich talents (Stefan 18.10.2026, Vertrag Migration 47)
const w = String(raw).toLowerCase().match(/\b(kalender|mail|belege|projekte|marketing|talents|einstellungen|alles)\b/);
return { json: { ...$('6_9_v2_vorsortierung').item.json, bereich: w ? w[1] : 'alles', quelle: w ? 'ki' : 'ki_unklar' } };

// Daten für Ally zusammenstellen: Eingang aus der Vorsortierung plus der gespeicherte Bereich.
// Ohne gespeicherten Bereich (Fehler beim Speichern) bekommt Ally alle Werkzeuge.
const v = $('6_9_v2_vorsortierung').item.json;
const bereich = $input.item.json.bereich || 'alles';
return { json: { ...v, bereich } };

// Agent ist gescheitert: feste Antwort statt Schweigen, Fehler fuer die Meldung merken
const e = $json.error;
const msg = String((e && (e.message || e.description)) || e || 'unbekannt').slice(0, 300);
return { json: {
  output: 'Da ist gerade etwas schiefgelaufen, ich konnte deine Nachricht nicht beantworten.\n\nBitte schreib sie mir noch einmal.',
  fehler: msg
} };

// Platzhalter in eckigen Klammern im Chat rot (Vorgabe Stefan, 13.10.2026). Markdown-Links [Text](Adresse) bleiben unberührt.
// Klappt das Einfärben nicht, geht die Antwort unverändert raus.
const ROT = '#D00000';
const j = $input.item.json;
let html = j.html;
try {
  html = String(j.html || '').replace(/\[([^\[\]\n<>]{1,150})\](?!\()/g, '<font color="' + ROT + '" data-mx-color="' + ROT + '">[$1]</font>');
} catch (e) { html = j.html; }
return { json: { text: j.text, html } };

